const D = { energy: .5, scale: 1, density: .5, speed: 1, hue: 210, twill: .6, x: .5, y: .5, style: 'black_watch', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const uMin=Math.min(width,height), t=K.t||0;
const drift=0.9*Math.sin(t*0.61)+0.5*Math.sin(t*1.43+1.7)+0.32*Math.sin(t*2.29);
const fr=i=>{ const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s); };
function h2r(h,s,v){ h=((h%360)+360)%360; const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c; let r,g,b; const hp=h/60;
  if(hp<1){r=c;g=x;b=0;}else if(hp<2){r=x;g=c;b=0;}else if(hp<3){r=0;g=c;b=x;}else if(hp<4){r=0;g=x;b=c;}else if(hp<5){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
  return [(r+m)*255,(g+m)*255,(b+m)*255]; }

function palette(style,hue){
  if(style==='royal_stewart') return {cols:[[hue-208,.78,.72],[142,.60,.34],[222,.55,.32],[0,0,.94],[48,.80,.80]], sheen:.30, matte:0.7};
  if(style==='hunting_moss')  return {cols:[[104,.42,.30],[36,.44,.30],[150,.36,.24],[28,.30,.42],[70,.30,.20]], sheen:.16, matte:0.85};
  if(style==='dress_mono')    return {cols:[[0,0,.10],[0,0,.92],[0,0,.55],[0,0,.74],[0,0,.30]], sheen:.10, matte:1.0};
  if(style==='faded_antique') return {cols:[[hue,.28,.44],[110,.24,.40],[18,.30,.46],[44,.24,.66],[0,0,.30]], sheen:.14, matte:0.9};
  return {cols:[[hue,.62,.32],[145,.55,.31],[0,0,.12],[hue-10,.40,.46],[150,.30,.24]], sheen:.18, matte:0.85}; // black_watch
}
const PL=palette(P.style,P.hue);

const key=[P.style,P.seed,Math.round(P.density*24),Math.round(P.hue),Math.round(P.scale*20)].join('_');
if(S.key!==key || !S.g){
  S.key=key;
  // build symmetric sett: pivot sequence of (colorIdx,count) then mirror
  const nC=PL.cols.length; const counts=[2,4,6,8,12,16,24]; const nStripe=Math.round(4+P.density*6);
  const piv=[]; for(let i=0;i<nStripe;i++){ const ci=Math.floor(fr(i*3+1)*nC); const cn=counts[Math.floor(fr(i*3+2)*counts.length)]; piv.push([ci,cn]); }
  // expand palindrome sett -> thread color array
  const seq=[]; for(const s of piv) for(let k=0;k<s[1];k++) seq.push(s[0]);
  for(let i=piv.length-2;i>=1;i--){ for(let k=0;k<piv[i][1];k++) seq.push(piv[i][0]); }
  const nT=seq.length;
  const tw=Math.max(3,Math.round(4*P.scale));      // px per thread
  const dim=Math.min(760, nT*tw);
  const g=createGraphics(dim,dim); g.pixelDensity(1); g.loadPixels();
  const rgb=PL.cols.map(c=>h2r(c[0],c[1],c[2])); // s,v in 0..1
  const matte=PL.matte, tw2=P.twill;
  for(let y=0;y<dim;y++){
    const j=(Math.floor(y/tw))%nT; const wc=seq[j]; const sy=(y%tw)/tw;
    for(let x=0;x<dim;x++){
      const i=(Math.floor(x/tw))%nT; const wr=seq[i]; const sx=(x%tw)/tw;
      const warpUp=((((i - j)%4)+4)%4) < 2;
      const col = warpUp? rgb[wr] : rgb[wc];
      // round-thread cylindrical shading along the visible thread
      const rough = warpUp? Math.sin(Math.PI*sx) : Math.sin(Math.PI*sy);
      let sh = (0.72 + 0.34*rough);
      sh = 1 + (sh-1)*matte;                          // flatten for graphic styles
      // twill float shadow at the 45deg boundary + wale emphasis
      const wale = 0.5+0.5*Math.sin((x - y)*(Math.PI/2/tw));
      sh *= (0.94 + 0.10*wale*tw2);
      const idx=4*(y*dim+x);
      g.pixels[idx]  =Math.max(0,Math.min(255,col[0]*sh));
      g.pixels[idx+1]=Math.max(0,Math.min(255,col[1]*sh));
      g.pixels[idx+2]=Math.max(0,Math.min(255,col[2]*sh));
      g.pixels[idx+3]=255;
    }
  }
  g.updatePixels(); S.g=g; S.dim=dim;
  if(!S.sheen){ const sh=createGraphics(200,200); sh.pixelDensity(1); sh.noStroke();
    for(let r=100;r>0;r--){ const a=Math.pow(1-r/100,1.7)*80; sh.fill(46,10,100,a); sh.ellipse(100,100,r*2,r*2);} S.sheen=sh; }
}

// on-screen tile size chosen so upscale stays near 1x
const reps=Math.max(2,Math.round(width/(uMin*0.62*P.scale)));
const tsz=width/reps;
S.scroll=(S.scroll||0)+(0.35+0.7*P.speed)*(1+0.4*A.bass*P.energy);
