for(let j=-1;j<ny;j++) for(let i=-1;i<nx;i++) image(S.g, i*tsz+(xdr%tsz), j*tsz-ph, tsz, tsz);
// soft wool sheen sweep
const shA=PL.sheen*(0.5+0.9*P.energy)*(0.6+0.6*K.swell);
if(shA>0.02){ blendMode(ADD); imageMode(CENTER);
  const cx=width*(0.5+0.4*Math.sin(t*0.17+P.x*3)), cy=height*(0.5+0.42*Math.sin(t*0.23+0.5));
  tint(255,255*Math.min(1,shA)); image(S.sheen,cx,cy,uMin*1.6,uMin*0.9); noTint(); blendMode(BLEND); }
if(P.alpha<100){ noStroke(); fill(PL.cols[0][0],PL.cols[0][1]*100,PL.cols[0][2]*100,100-P.alpha); rect(0,0,width,height); }
